          'package main\n\nimport (\n\t"context"\n\t"fmt"\n\n\t"github.com/run-llama/llama-parse-go"\n\t"github.com/run-llama/llama-parse-go/option"\n)\n\nfunc main() {\n\tclient := llamacloud.NewClient(\n\t\toption.WithAPIKey("My API Key"),\n\t)\n\tconfigurationCreate, err := client.Extract.GenerateSchema(context.TODO(), llamacloud.ExtractGenerateSchemaParams{\n\t\tExtractV2SchemaGenerateRequest: llamacloud.ExtractV2SchemaGenerateRequestParam{},\n\t})\n\tif err != nil {\n\t\tpanic(err.Error())\n\t}\n\tfmt.Printf("%+v\\n", configurationCreate.Name)\n}\n',
